using System;
using System.Threading;
using System.Threading.Tasks;

// Eksperimen Thread Id pada Async/Await
public class Program
{
    public static async Task Main()
    {
        Console.WriteLine($"[1] Sebelum await: Thread ID = {Environment.CurrentManagedThreadId}");

        // Lakukan operasi I/O asinkronus simulasi
        await SimulateIoOperationAsync();

        Console.WriteLine($"[3] Setelah await:  Thread ID = {Environment.CurrentManagedThreadId}");

        // TODO:
        // Amati apakah Thread ID pada langkah [1] dan langkah [3] sama atau berbeda.
        // Tuliskan kesimpulan singkat di console menggunakan Console.WriteLine.
    }

    private static async Task SimulateIoOperationAsync()
    {
        Console.WriteLine($"[2] Di dalam method async: Thread ID = {Environment.CurrentManagedThreadId}");

        // Task.Delay mensimulasikan non-blocking timer OS (bukan Thread.Sleep!)
        await Task.Delay(100);
    }
}

solutionCode:
using System;
using System.Threading;
using System.Threading.Tasks;

public class Program
{
    public static async Task Main()
    {
        int initialThread = Environment.CurrentManagedThreadId;
        Console.WriteLine($"[1] Sebelum await: Thread ID = {initialThread}");

        await SimulateIoOperationAsync();

        int resumeThread = Environment.CurrentManagedThreadId;
        Console.WriteLine($"[3] Setelah await:  Thread ID = {resumeThread}");

        Console.WriteLine("\nKesimpulan Internal .NET:");
        Console.WriteLine("Thread awal dibebaskan ke ThreadPool saat Task.Delay aktif.");
        Console.WriteLine("Continuation dapat dieksekusi oleh thread mana saja yang tersedia di ThreadPool.");
    }

    private static async Task SimulateIoOperationAsync()
    {
        Console.WriteLine($"[2] Di dalam method async: Thread ID = {Environment.CurrentManagedThreadId}");
        await Task.Delay(100);
    }
}
